import io.netty.channel.Channel;
import java.util.Date;
import java.net.SocketAddress;
import org.traccar.Protocol;
import org.mockito.Mockito;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class WatchProtocolDecoderTest {

    @Test
    public void WatchProtocolDecoderConstructionTest() {
        Protocol testProtocol = new Protocol("testProtocol");
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(testProtocol);

        assertNotNull(decoder);
        assertEquals(testProtocol, decoder.getProtocol());
    }

    @Test
    public void getHasIndexTest() {
        Protocol testProtocol = new Protocol("testProtocol");
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(testProtocol);
        assertFalse(decoder.getHasIndex());

        decoder.setHasIndex(true);
        assertTrue(decoder.getHasIndex());
    }

    @Test
    public void getManufacturerDefaultTest() {
        Protocol testProtocol = new Protocol("testProtocol");
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(testProtocol);

        assertEquals("unknown", decoder.getManufacturer());
    }

    @Test
    public void getManufacturerSetTest() {
        Protocol testProtocol = new Protocol("testProtocol");
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(testProtocol);

        decoder.setManufacturer("testManufacturer");
        assertEquals("testManufacturer", decoder.getManufacturer());
    }

    @Test
    public void decodeTest() throws Exception {
        Protocol testProtocol = new Protocol("testProtocol");
        SocketAddress testAddress = Mockito.mock(SocketAddress.class);
        Channel testChannel = Mockito.mock(Channel.class);
        Object msg = "testMessage";

        WatchProtocolDecoder decoder = new WatchProtocolDecoder(testProtocol);

        Object result = decoder.decode(testChannel, testAddress, msg);
        assertNotNull(result);
    }
}
